func prevMonthPath(year, month int) string {
	if month == 1 {
		return fmt.Sprintf("/calendar/%d/12", year-1)
	}
	return fmt.Sprintf("/calendar/%d/%d", year, month-1)
}

func nextMonthPath(year, month int) string {
	if month == 12 {
		return fmt.Sprintf("/calendar/%d/1", year+1)
	}
	return fmt.Sprintf("/calendar/%d/%d", year, month+1)
}

func monthName(month int) string {
	return time.Month(month).String()
}

func dayCellClass(day DayCell) string {
	cls := "day-cell"
	if !day.IsCurrentMonth {
		cls += " other-month"
	}
	if day.IsToday {
		cls += " today"
	}
	return cls
}

// formatEventTime renders an event's start in the user's calendar zone, the
// zone the views place it in.
func formatEventTime(ctx context.Context, unix int64) string {
	return time.Unix(unix, 0).In(calendarNow(ctx).Location()).Format("15:04")
}

func formatEventDate(ctx context.Context, unix int64) string {
	if unix == 0 {
		return "-"
	}
	return time.Unix(unix, 0).In(calendarNow(ctx).Location()).Format("Jan 2, 2006")
}

// formatEventListDate formats an event's start date for lists. An all-day
// event is a UTC calendar date, so no zone shifts it.
func formatEventListDate(ctx context.Context, e *bongov1.Event) string {
	if e.AllDay {
		return icalevent.AllDayDate(e.StartTime).Format("Jan 2, 2006")
	}
	return formatEventDate(ctx, e.StartTime)
}

func truncateTitle(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	return s[:maxLen-1] + "..."
}

// eventAttendeesValue is the attendees input's initial text: one "Name <addr>"
// entry per attendee, in the form parseAttendees reads back.
func eventAttendeesValue(e *bongov1.Event) string {
	if e == nil {
		return ""
	}
	parts := make([]string, 0, len(e.Attendees))
	for _, a := range e.Attendees {
		parts = append(parts, attendeeEntry(a))
	}
	return strings.Join(parts, ", ")
}

// attendeeEntry is one "Name <addr>" entry. It is built by hand because
// mail.Address.String would RFC 2047-encode a non-ASCII name, and the field
// is plain text the user reads and edits. A name holding an RFC 5322 special
// is quoted, with the quote and backslash escaped, so the list parser reads it
// back unchanged.
func attendeeEntry(a *bongov1.Attendee) string {
	if a.Name == "" {
		return a.Address
	}
	name := a.Name
	if strings.ContainsAny(name, "()<>[]:;@\\,.\"") {
		name = `"` + strings.NewReplacer(`\`, `\\`, `"`, `\"`).Replace(name) + `"`
	}
	return name + " <" + a.Address + ">"
}

// attendeeLabel is the name an attendee is listed under.
func attendeeLabel(a *bongov1.Attendee) string {
	if a.Name != "" {
		return a.Name + " <" + a.Address + ">"
	}
	return a.Address
}

// attendeeStatusClass is the CSS modifier for an attendee's PARTSTAT. An
// unset or unknown value reads as needs-action.
func attendeeStatusClass(partstat string) string {
	switch strings.ToUpper(partstat) {
	case "ACCEPTED":
		return "accepted"
	case "DECLINED":
		return "declined"
	case "TENTATIVE":
		return "tentative"
	case "DELEGATED":
		return "delegated"
	}
	return "needs-action"
}

// attendeeStatusKey is the message ID of the badge text for a PARTSTAT.
func attendeeStatusKey(partstat string) string {
	switch attendeeStatusClass(partstat) {
	case "accepted":
		return "calendar.partstat.accepted"
	case "declined":
		return "calendar.partstat.declined"
	case "tentative":
		return "calendar.partstat.tentative"
	case "delegated":
		return "calendar.partstat.delegated"
	}
	return "calendar.partstat.needsAction"
}

func eventTitle(e *bongov1.Event) string {
	if e == nil {
		return ""
	}
	return e.Title
}

func eventDescription(e *bongov1.Event) string {
	if e == nil {
		return ""
	}
	return e.Description
}

func eventLocation(e *bongov1.Event) string {
	if e == nil {
		return ""
	}
	return e.Location
}

func eventStartDate(ctx context.Context, e *bongov1.Event, date string) string {
	if e != nil && e.StartTime > 0 {
		if e.AllDay {
			return icalevent.AllDayDate(e.StartTime).Format("2006-01-02")
		}
		return time.Unix(e.StartTime, 0).In(calendarNow(ctx).Location()).Format("2006-01-02")
	}
	if date != "" {
		return date
	}
	return calendarNow(ctx).Format("2006-01-02")
}

func eventStartTime(ctx context.Context, e *bongov1.Event) string {
	if e != nil && e.StartTime > 0 && !e.AllDay {
		return time.Unix(e.StartTime, 0).In(calendarNow(ctx).Location()).Format("15:04")
	}
	return "09:00"
}

func eventEndDate(ctx context.Context, e *bongov1.Event, date string) string {
	if e != nil && e.EndTime > 0 {
		t := time.Unix(e.EndTime, 0).In(calendarNow(ctx).Location())
		if e.AllDay {
			t = icalevent.AllDayDate(e.EndTime).AddDate(0, 0, -1)
		}
		return t.Format("2006-01-02")
	}
	if date != "" {
		return date
	}
	return calendarNow(ctx).Format("2006-01-02")
}

func eventEndTime(ctx context.Context, e *bongov1.Event) string {
	if e != nil && e.EndTime > 0 && !e.AllDay {
		return time.Unix(e.EndTime, 0).In(calendarNow(ctx).Location()).Format("15:04")
	}
	return "10:00"
}

func eventFormData(e *bongov1.Event, isNew bool, date string) string {
	allDay := "false"
	if e != nil && e.AllDay {
		allDay = "true"
	}
	return fmt.Sprintf("{allDay: %s}", allDay)
}

func prevWeekYear(year, week int) int {
	if week <= 1 {
		return year - 1
	}
	return year
}

func prevWeekNum(year, week int) int {
	if week <= 1 {
		return 52
	}
	return week - 1
}

func nextWeekYear(year, week int) int {
	if week >= 52 {
		return year + 1
	}
	return year
}

func nextWeekNum(year, week int) int {
	if week >= 52 {
		return 1
	}
	return week + 1
}

func prevDayPath(date time.Time) string {
	d := date.AddDate(0, 0, -1)
	return fmt.Sprintf("/calendar/day/%d/%d/%d", d.Year(), int(d.Month()), d.Day())
}

func nextDayPath(date time.Time) string {
	d := date.AddDate(0, 0, 1)
	return fmt.Sprintf("/calendar/day/%d/%d/%d", d.Year(), int(d.Month()), d.Day())
}

func dateISOYear(date time.Time) int {
	y, _ := date.ISOWeek()
	return y
}

func dateISOWeek(date time.Time) int {
	_, w := date.ISOWeek()
	return w
}

func eventBlockColor(e *bongov1.Event, calColors map[string]string) string {
	if c, ok := calColors[e.CalendarId]; ok && c != "" {
		return c
	}
	return "#4A90D9"
}

// eventCalendarID is the calendar an event is shown under for the sidebar's
// show/hide filter; an event with no calendar belongs to the default one.
func eventCalendarID(e *bongov1.Event) string {
	if e.CalendarId == "" {
		return "default"
	}
	return e.CalendarId
}

func eventBlockColourClass(e *bongov1.Event, calColors map[string]string) string {
	return CalendarColourClass(eventBlockColor(e, calColors))
}

// EventColourClass is the cal-colour-* class for an event's calendar.
func EventColourClass(e *bongov1.Event, calColors map[string]string) string {
	return eventBlockColourClass(e, calColors)
}

func calendarTopClass(minutes int) string {
	if minutes < 0 {
		minutes = 0
	}
	if minutes > 1439 {
		minutes = 1439
	}
	return fmt.Sprintf("cal-top-%d", minutes)
}

func calendarHeightClass(minutes int) string {
	if minutes < 30 {
		minutes = 30
	}
	if minutes > 1440 {
		minutes = 1440
	}
	return fmt.Sprintf("cal-height-%d", minutes)
}

func CalendarColourClass(hex string) string {
	type paletteEntry struct {
		name    string
		r, g, b int
	}
	palette := []paletteEntry{
		{"blue", 59, 130, 246},
		{"green", 34, 197, 94},
		{"indigo", 99, 102, 241},
		{"orange", 245, 158, 11},
		{"red", 239, 68, 68},
		{"violet", 139, 92, 246},
		{"yellow", 234, 179, 8},
	}
	r, g, b, ok := parseHexColour(hex)
	if !ok {
		return "cal-colour-blue"
	}
	bestName := "blue"
	bestDist := -1
	for _, p := range palette {
		dr := r - p.r
		dg := g - p.g
		db := b - p.b
		dist := dr*dr + dg*dg + db*db
		if bestDist == -1 || dist < bestDist {
			bestDist = dist
			bestName = p.name
		}
	}
	return "cal-colour-" + bestName
}

func parseHexColour(hex string) (int, int, int, bool) {
	if len(hex) != 7 || hex[0] != '#' {
		return 0, 0, 0, false
	}
	var r, g, b int
	_, err := fmt.Sscanf(hex, "#%02x%02x%02x", &r, &g, &b)
	if err != nil {
		return 0, 0, 0, false
	}
	return r, g, b, true
}

// isCustomRrule reports whether a stored rule is not one of the form presets,
// so the select can offer it and round-trip it unchanged.
func isCustomRrule(r string) bool {
	switch r {
	case "", "FREQ=DAILY", "FREQ=WEEKLY", "FREQ=MONTHLY", "FREQ=YEARLY":
		return false
	}
	return true
}

func eventRrule(e *bongov1.Event) string {
	if e == nil {
		return ""
	}
	return e.Rrule
}

func eventReminderMinutes(e *bongov1.Event) string {
	if e == nil || e.ReminderMinutes == 0 {
		return "0"
	}
	return fmt.Sprint(e.ReminderMinutes)
}

// MiniCalDay holds data for one day in the mini calendar.
type MiniCalDay struct {
	Day        int
	IsToday    bool
	IsSelected bool
	InMonth    bool
}

func miniCalDays(today time.Time, year, month, selectedDay int) []MiniCalDay {
	firstDay := time.Date(year, time.Month(month), 1, 0, 0, 0, 0, today.Location())
	lastDay := firstDay.AddDate(0, 1, -1).Day()

	weekday := int(firstDay.Weekday())
	if weekday == 0 {
		weekday = 7
	}

	todayYear, todayMonth, todayDay := today.Date()

	var days []MiniCalDay

	// Padding for days before month start.
	for i := 1; i < weekday; i++ {
		days = append(days, MiniCalDay{Day: 0})
	}

	for d := 1; d <= lastDay; d++ {
		days = append(days, MiniCalDay{
			Day:        d,
			IsToday:    year == todayYear && time.Month(month) == todayMonth && d == todayDay,
			IsSelected: d == selectedDay,
			InMonth:    true,
		})
	}

	return days
}

func firstOfMonth(ctx context.Context, year, month int) time.Time {
	return time.Date(year, time.Month(month), 1, 0, 0, 0, 0, calendarNow(ctx).Location())
}

func miniPrevYear(year, month int) int {
	if month <= 1 {
		return year - 1
	}
	return year
}

func miniPrevMonth(month int) int {
	if month <= 1 {
		return 12
	}
	return month - 1
}

func miniNextYear(year, month int) int {
	if month >= 12 {
		return year + 1
	}
	return year
}

func miniNextMonth(month int) int {
	if month >= 12 {
		return 1
	}
	return month + 1
}

// AgendaItem is one row of the agenda. TimeLabel is formatted by the handler
